s=s.replace("if(s.answer_tendency) lines.push(`答案傾向：${s.answer_tendency==='yes'?'是':s.answer_tendency==='no'?'否':'尚不明確'}`);","if(s.answer_tendency){const value=s.answer_tendency==='yes'?rt('yes','Yes'):s.answer_tendency==='no'?rt('no','No'):rt('unclear','Unclear');lines.push(rt('answer_tendency','Answer tendency: {value}',{value}));}")
